examples.code:
for (let n = 1; n <= 6; n++) {
  if (n === 4) break;
  console.log(n);
}

for (let n = 1; n <= 5; n++) {
  if (n === 3) continue;
  console.log(n);
}

const values = [-2, 0, 5, 7, -1];
for (const value of values) {
  if (value <= 0) continue;
  console.log(value);
}

for (let row = 1; row <= 2; row++) {
  for (let col = 1; col <= 4; col++) {
    if (col === 3) break;
    console.log(row + ':' + col);
  }
}

for (let n = 0; n < 6; n++) {
  if (n % 2 === 0) continue;
  console.log(n);
}

